29	  /// Parses [Plugin] specification from the provided pluginYaml.
30	  ///
31	  /// This currently supports two formats. Legacy and Multi-platform.
32	  ///
33	  /// Example of the deprecated Legacy format.
34	  ///
35	  ///     flutter:
36	  ///      plugin:
37	  ///        androidPackage: io.flutter.plugins.sample
38	  ///        iosPrefix: FLT
39	  ///        pluginClass: SamplePlugin
40	  ///
41	  /// Example Multi-platform format.
42	  ///
43	  ///     flutter:
44	  ///      plugin:
45	  ///        platforms:
46	  ///          android:
47	  ///            package: io.flutter.plugins.sample
48	  ///            pluginClass: SamplePlugin
49	  ///          ios:
50	  ///            pluginClass: SamplePlugin
51	  ///          linux:
52	  ///            pluginClass: SamplePlugin
53	  ///          macos:
54	  ///            pluginClass: SamplePlugin
55	  ///          windows:
56	  ///            pluginClass: SamplePlugin
57	  factory Plugin.fromYaml(
58	    String name,
59	    String path,
60	    YamlMap? pluginYaml,
61	    List<String> dependencies, {
62	    required FileSystem fileSystem,
63	    Set<String>? appDependencies,
64	  }) {
65	    final List<String> errors = validatePluginYaml(pluginYaml);
66	    if (errors.isNotEmpty) {
67	      throwToolExit('Invalid plugin specification $name.\n${errors.join('\n')}');
68	    }
69	    if (pluginYaml != null && pluginYaml['platforms'] != null) {
70	      return Plugin._fromMultiPlatformYaml(
71	        name,
72	        path,
73	        pluginYaml,
74	        dependencies,
75	        fileSystem,
76	        appDependencies != null && appDependencies.contains(name),
77	      );
78	    }
79	    return Plugin._fromLegacyYaml(
80	      name,
81	      path,
82	      pluginYaml,
83	      dependencies,
84	      fileSystem,
85	      appDependencies != null && appDependencies.contains(name),
86	    );
87	  }
