89	  factory Plugin._fromMultiPlatformYaml(
90	    String name,
91	    String path,
92	    YamlMap pluginYaml,
93	    List<String> dependencies,
94	    FileSystem fileSystem,
95	    bool isDirectDependency,
96	  ) {
97	    assert (pluginYaml['platforms'] != null, 'Invalid multi-platform plugin specification $name.');
98	    final YamlMap platformsYaml = pluginYaml['platforms'] as YamlMap;
99	
100	    assert (_validateMultiPlatformYaml(platformsYaml).isEmpty,
101	            'Invalid multi-platform plugin specification $name.');
102	
103	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
104	
105	    if (_providesImplementationForPlatform(platformsYaml, AndroidPlugin.kConfigKey)) {
106	      platforms[AndroidPlugin.kConfigKey] = AndroidPlugin.fromYaml(
107	        name,
108	        platformsYaml[AndroidPlugin.kConfigKey] as YamlMap,
109	        path,
110	        fileSystem,
111	      );
112	    }
113	
114	    if (_providesImplementationForPlatform(platformsYaml, IOSPlugin.kConfigKey)) {
115	      platforms[IOSPlugin.kConfigKey] =
116	          IOSPlugin.fromYaml(name, platformsYaml[IOSPlugin.kConfigKey] as YamlMap);
117	    }
118	
119	    if (_providesImplementationForPlatform(platformsYaml, LinuxPlugin.kConfigKey)) {
120	      platforms[LinuxPlugin.kConfigKey] =
121	          LinuxPlugin.fromYaml(name, platformsYaml[LinuxPlugin.kConfigKey] as YamlMap);
122	    }
123	
124	    if (_providesImplementationForPlatform(platformsYaml, MacOSPlugin.kConfigKey)) {
125	      platforms[MacOSPlugin.kConfigKey] =
126	          MacOSPlugin.fromYaml(name, platformsYaml[MacOSPlugin.kConfigKey] as YamlMap);
127	    }
128	
129	    if (_providesImplementationForPlatform(platformsYaml, WebPlugin.kConfigKey)) {
130	      platforms[WebPlugin.kConfigKey] =
131	          WebPlugin.fromYaml(name, platformsYaml[WebPlugin.kConfigKey] as YamlMap);
132	    }
133	
134	    if (_providesImplementationForPlatform(platformsYaml, WindowsPlugin.kConfigKey)) {
135	      platforms[WindowsPlugin.kConfigKey] =
136	          WindowsPlugin.fromYaml(name, platformsYaml[WindowsPlugin.kConfigKey] as YamlMap);
137	    }
138	
139	    // TODO(stuartmorgan): Consider merging web into this common handling; the
140	    // fact that its implementation of Dart-only plugins and default packages
141	    // are separate is legacy.
142	    final List<String> sharedHandlingPlatforms = <String>[
143	      AndroidPlugin.kConfigKey,
144	      IOSPlugin.kConfigKey,
145	      LinuxPlugin.kConfigKey,
146	      MacOSPlugin.kConfigKey,
147	      WindowsPlugin.kConfigKey,
148	    ];
149	    final Map<String, String> defaultPackages = <String, String>{};
150	    final Map<String, String> dartPluginClasses = <String, String>{};
151	    for (final String platform in sharedHandlingPlatforms) {
152	        final String? defaultPackage = _getDefaultPackageForPlatform(platformsYaml, platform);
153	        if (defaultPackage != null) {
154	          defaultPackages[platform] = defaultPackage;
155	        }
156	        final String? dartClass = _getPluginDartClassForPlatform(platformsYaml, platform);
157	        if (dartClass != null) {
158	          dartPluginClasses[platform] = dartClass;
159	        }
160	    }
161	
162	    return Plugin(
163	      name: name,
164	      path: path,
165	      platforms: platforms,
166	      defaultPackagePlatforms: defaultPackages,
167	      pluginDartClassPlatforms: dartPluginClasses,
168	      dependencies: dependencies,
169	      isDirectDependency: isDirectDependency,
170	      implementsPackage: pluginYaml['implements'] != null ? pluginYaml['implements'] as String : '',
171	    );
172	  }
