174	  factory Plugin._fromLegacyYaml(
175	    String name,
176	    String path,
177	    dynamic pluginYaml,
178	    List<String> dependencies,
179	    FileSystem fileSystem,
180	    bool isDirectDependency,
181	  ) {
182	    final Map<String, PluginPlatform> platforms = <String, PluginPlatform>{};
183	    final String pluginClass = (pluginYaml as Map<dynamic, dynamic>)['pluginClass'] as String;
184	    if (pluginYaml != null && pluginClass != null) {
185	      final String androidPackage = pluginYaml['androidPackage'] as String;
186	      if (androidPackage != null) {
187	        platforms[AndroidPlugin.kConfigKey] = AndroidPlugin(
188	          name: name,
189	          package: pluginYaml['androidPackage'] as String,
190	          pluginClass: pluginClass,
191	          pluginPath: path,
192	          fileSystem: fileSystem,
193	        );
194	      }
195	
196	      final String iosPrefix = pluginYaml['iosPrefix'] as String? ?? '';
197	      platforms[IOSPlugin.kConfigKey] =
198	          IOSPlugin(
199	            name: name,
200	            classPrefix: iosPrefix,
201	            pluginClass: pluginClass,
202	          );
203	    }
204	    return Plugin(
205	      name: name,
206	      path: path,
207	      platforms: platforms,
208	      defaultPackagePlatforms: <String, String>{},
209	      pluginDartClassPlatforms: <String, String>{},
210	      dependencies: dependencies,
211	      isDirectDependency: isDirectDependency,
212	    );
213	  }
