103	/// Filters [plugins] to those supported by [platformKey].
104	List<Map<String, Object>> _filterPluginsByPlatform(List<Plugin> plugins, String platformKey) {
105	  final Iterable<Plugin> platformPlugins = plugins.where((Plugin p) {
106	    return p.platforms.containsKey(platformKey);
107	  });
108	
109	  final Set<String> pluginNames = platformPlugins.map((Plugin plugin) => plugin.name).toSet();
110	  final List<Map<String, Object>> pluginInfo = <Map<String, Object>>[];
111	  for (final Plugin plugin in platformPlugins) {
112	    // This is guaranteed to be non-null due to the `where` filter above.
113	    final PluginPlatform platformPlugin = plugin.platforms[platformKey]!;
114	    pluginInfo.add(<String, Object>{
115	      _kFlutterPluginsNameKey: plugin.name,
116	      _kFlutterPluginsPathKey: globals.fsUtils.escapePath(plugin.path),
117	      if (platformPlugin is NativeOrDartPlugin)
118	        _kFlutterPluginsHasNativeBuildKey: (platformPlugin as NativeOrDartPlugin).isNative(),
119	      _kFlutterPluginsDependenciesKey: <String>[...plugin.dependencies.where(pluginNames.contains)],
120	    });

